#!/usr/bin/env python3
"""Extract actor_loss timeseries from worker logs - v2."""
import json
import re
import os
import sys

LOGS_DIR = "/home/ubuntu/.agent-ml-research-idea_gen_0509_9/projects/event-gated-adaptive-horizon/logs/workers"
TOOL_RESULT_FILE = "/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-9-projects-event-gated-adaptive-horizon/b6e6ee49-6f83-49e9-b3c1-bb4c799f6903/tool-results/b82k9i353.txt"

EXP_PATTERNS = {
    "008d_s1": ["exp_008d_subsample_on_h8", "008d_subsample"],
    "009b_s2": ["exp_009b_008d_walker_s2", "009b_008d_walker"],
    "009e_s1": ["exp_009e_008d_walker_s1", "009e_008d_walker"],
}

LOG_FILES = [
    "worker_analysis_exp_009b_008d_walker_s2_20260514T184904.log",
    "worker_ops_check-009e-status_20260515T100311.log",
    "worker_research_check_008d_45k_20260514T044622.log",
    "worker_analysis_metrics-aggregation_20260515T041903.log",
    "worker_analysis_metrics-aggregation_20260515T043938.log",
    "worker_analysis_metrics-consolidation_20260515T041953.log",
    "worker_monitor_live-metrics-check_20260515T043832.log",
    "worker_monitor_live-metrics-check_20260515T045604.log",
    "worker_check_all_running_metrics_20260514T040636.log",
]

def identify_experiment(text):
    """Identify which experiment a text refers to."""
    for exp_name, patterns in EXP_PATTERNS.items():
        for pat in patterns:
            if pat in text:
                return exp_name
    return None

def extract_step_actor_loss_from_stdout(stdout_text):
    """Extract (step, actor_loss) pairs from stdout text (metrics.jsonl content)."""
    results = []
    for line in stdout_text.strip().split('\n'):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
            if isinstance(obj, dict) and 'step' in obj and 'actor_loss' in obj:
                results.append((int(obj['step']), float(obj['actor_loss'])))
        except:
            pass
    return results

def unwrap_tool_result_content(content_str):
    """Unwrap nested JSON in tool result content to get stdout."""
    stdouts = []
    try:
        obj = json.loads(content_str)
    except:
        return stdouts

    # Handle different nesting structures
    if isinstance(obj, dict):
        # Direct: {"result": "{\"success\": true, \"data\": {\"stdout\": \"...\"}}"} 
        if 'result' in obj:
            result = obj['result']
            if isinstance(result, str):
                try:
                    inner = json.loads(result)
                    if isinstance(inner, dict):
                        if 'data' in inner and isinstance(inner['data'], dict):
                            stdout = inner['data'].get('stdout', '')
                            if stdout:
                                stdouts.append(stdout)
                        if 'success' in inner and 'data' in inner:
                            data = inner['data']
                            if isinstance(data, dict) and 'stdout' in data:
                                stdouts.append(data['stdout'])
                except:
                    pass
            elif isinstance(result, dict):
                if 'data' in result and isinstance(result['data'], dict):
                    stdout = result['data'].get('stdout', '')
                    if stdout:
                        stdouts.append(stdout)
        # Direct data/stdout
        if 'data' in obj and isinstance(obj['data'], dict):
            stdout = obj['data'].get('stdout', '')
            if stdout:
                stdouts.append(stdout)
        if 'stdout' in obj:
            stdouts.append(obj['stdout'])
    elif isinstance(obj, str):
        # String that needs further unwrapping
        stdouts.extend(unwrap_tool_result_content(obj))

    return stdouts

def process_log_file(log_path):
    """Process a log file and return {exp_name: [(step, actor_loss), ...]}."""
    results = {}

    if not os.path.exists(log_path):
        return results

    # We need to track which tool_use_id maps to which experiment
    # by looking at the SSH commands in assistant messages
    tool_to_exp = {}

    with open(log_path, 'r', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            # Skip non-JSON lines
            if not line.startswith('{'):
                continue

            try:
                entry = json.loads(line)
            except:
                continue

            entry_type = entry.get('type')

            # Track assistant tool_use calls to map tool_use_id -> experiment
            if entry_type == 'assistant':
                msg = entry.get('message', {})
                content = msg.get('content', [])
                for item in content:
                    if isinstance(item, dict) and item.get('type') == 'tool_use':
                        tool_id = item.get('id', '')
                        inp = item.get('input', {})
                        cmd = inp.get('command', '')
                        exp = identify_experiment(cmd)
                        if exp:
                            tool_to_exp[tool_id] = exp

            # Process user messages (tool results)
            if entry_type == 'user':
                msg = entry.get('message', {})
                content = msg.get('content', [])

                for item in content:
                    if not isinstance(item, dict) or item.get('type') != 'tool_result':
                        continue

                    tool_id = item.get('tool_use_id', '')
                    item_content = item.get('content', '')

                    if not isinstance(item_content, str):
                        continue
                    if 'actor_loss' not in item_content:
                        continue

                    # Determine experiment
                    exp = tool_to_exp.get(tool_id)
                    if not exp:
                        exp = identify_experiment(item_content)
                    if not exp:
                        # Check the structuredContent in tool_use_result
                        tur = entry.get('tool_use_result', {})
                        sc = tur.get('structuredContent', {})
                        if isinstance(sc, dict):
                            result_str = sc.get('result', '')
                            if isinstance(result_str, str):
                                exp = identify_experiment(result_str)

                    if not exp:
                        continue

                    # Extract stdout from the nested content
                    stdouts = unwrap_tool_result_content(item_content)

                    # Also try from structuredContent
                    tur = entry.get('tool_use_result', {})
                    sc = tur.get('structuredContent', {})
                    if isinstance(sc, dict):
                        result_str = sc.get('result', '')
                        if isinstance(result_str, str):
                            stdouts.extend(unwrap_tool_result_content(result_str))

                    for stdout in stdouts:
                        pairs = extract_step_actor_loss_from_stdout(stdout)
                        if pairs:
                            if exp not in results:
                                results[exp] = []
                            results[exp].extend(pairs)

            # Also check for assistant text messages that contain pre-parsed data
            if entry_type == 'assistant':
                msg = entry.get('message', {})
                content = msg.get('content', [])
                for item in content:
                    if isinstance(item, dict) and item.get('type') == 'text':
                        text = item.get('text', '')
                        if 'actor_loss' in text:
                            # Try to find formatted tables or JSON in text
                            for exp_name, patterns in EXP_PATTERNS.items():
                                for pat in patterns:
                                    if pat in text:
                                        # Try regex to extract step/actor_loss from text
                                        for m in re.finditer(r'"step"\s*:\s*(\d+).*?"actor_loss"\s*:\s*(-?[\d.eE+-]+)', text):
                                            try:
                                                step = int(m.group(1))
                                                al = float(m.group(2))
                                                if exp_name not in results:
                                                    results[exp_name] = []
                                                results[exp_name].append((step, al))
                                            except:
                                                pass

    return results


def process_tool_result_standalone(file_path):
    """Process the large standalone tool result file."""
    results = {}

    if not os.path.exists(file_path):
        return results

    tool_to_exp = {}

    with open(file_path, 'r', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line or not line.startswith('{'):
                continue

            try:
                entry = json.loads(line)
            except:
                continue

            # Same logic as process_log_file
            entry_type = entry.get('type')

            if entry_type == 'assistant':
                msg = entry.get('message', {})
                content = msg.get('content', [])
                for item in content:
                    if isinstance(item, dict) and item.get('type') == 'tool_use':
                        tool_id = item.get('id', '')
                        inp = item.get('input', {})
                        cmd = inp.get('command', '')
                        exp = identify_experiment(cmd)
                        if exp:
                            tool_to_exp[tool_id] = exp

            if entry_type == 'user':
                msg = entry.get('message', {})
                content = msg.get('content', [])

                for item in content:
                    if not isinstance(item, dict) or item.get('type') != 'tool_result':
                        continue

                    tool_id = item.get('tool_use_id', '')
                    item_content = item.get('content', '')

                    if not isinstance(item_content, str) or 'actor_loss' not in item_content:
                        continue

                    exp = tool_to_exp.get(tool_id)
                    if not exp:
                        exp = identify_experiment(item_content)

                    if not exp:
                        continue

                    stdouts = unwrap_tool_result_content(item_content)

                    tur = entry.get('tool_use_result', {})
                    sc = tur.get('structuredContent', {})
                    if isinstance(sc, dict):
                        result_str = sc.get('result', '')
                        if isinstance(result_str, str):
                            stdouts.extend(unwrap_tool_result_content(result_str))

                    for stdout in stdouts:
                        pairs = extract_step_actor_loss_from_stdout(stdout)
                        if pairs:
                            if exp not in results:
                                results[exp] = []
                            results[exp].extend(pairs)

    return results


def main():
    all_data = {exp: [] for exp in EXP_PATTERNS}

    # Process all log files
    for log_file in LOG_FILES:
        log_path = os.path.join(LOGS_DIR, log_file)
        file_results = process_log_file(log_path)
        for exp, pairs in file_results.items():
            all_data[exp].extend(pairs)
            print(f"  {log_file} -> {exp}: {len(pairs)} points", file=sys.stderr)

    # Process standalone tool result file
    tr_results = process_tool_result_standalone(TOOL_RESULT_FILE)
    for exp, pairs in tr_results.items():
        all_data[exp].extend(pairs)
        print(f"  tool-result-file -> {exp}: {len(pairs)} points", file=sys.stderr)

    # Deduplicate and sort
    output = {}
    for exp_name in EXP_PATTERNS:
        pairs = all_data[exp_name]
        if pairs:
            step_map = {}
            for step, al in pairs:
                step_map[step] = al
            sorted_steps = sorted(step_map.keys())
            output[exp_name] = {
                "steps": sorted_steps,
                "actor_loss": [step_map[s] for s in sorted_steps]
            }
            print(f"\n{exp_name}: {len(sorted_steps)} unique steps, range [{sorted_steps[0]}, {sorted_steps[-1]}]", file=sys.stderr)
        else:
            output[exp_name] = None
            print(f"\n{exp_name}: NO DATA FOUND", file=sys.stderr)

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
