import json, re, os

LOGS_DIR = "."
results = {"008d_s1": {}, "009b_s2": {}, "009e_s1": {}}

def identify_exp(text):
    if "exp_008d_subsample_on_h8" in text or "008d_subsample" in text:
        return "008d_s1"
    if "exp_009b_008d_walker_s2" in text or "009b_008d_walker" in text:
        return "009b_s2"
    if "exp_009e_008d_walker_s1" in text or "009e_008d_walker" in text:
        return "009e_s1"
    return None

def extract_from_stdout(stdout, exp):
    """Extract all (step, actor_loss) from stdout text."""
    pairs = []
    for sl in stdout.strip().split('\n'):
        sl = sl.strip()
        if not sl or 'actor_loss' not in sl:
            continue
        # Try JSON parse
        try:
            obj = json.loads(sl)
            if isinstance(obj, dict) and 'step' in obj and 'actor_loss' in obj:
                pairs.append((int(obj['step']), float(obj['actor_loss'])))
                continue
        except:
            pass
        # Try regex on partial JSON
        m_al = re.search(r'"actor_loss":\s*([-\d.eE+]+)', sl)
        m_step = re.search(r'"step":\s*(\d+)', sl)
        if m_al and m_step:
            pairs.append((int(m_step.group(1)), float(m_al.group(1))))
    return pairs

def unwrap_to_stdout(content_str):
    """Unwrap nested JSON to get stdout."""
    try:
        obj = json.loads(content_str)
        if isinstance(obj, str):
            return unwrap_to_stdout(obj)
        if isinstance(obj, dict):
            if 'result' in obj:
                return unwrap_to_stdout(json.dumps(obj['result']) if not isinstance(obj['result'], str) else obj['result'])
            if 'data' in obj and isinstance(obj['data'], dict):
                return obj['data'].get('stdout', '')
            if 'stdout' in obj:
                return obj['stdout']
    except:
        pass
    return ''

# Process all log files
all_logs = [f for f in os.listdir(LOGS_DIR) if f.endswith('.log')]
for logf in sorted(all_logs):
    tool_to_exp = {}
    with open(logf, 'r', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line or not line.startswith('{'):
                continue
            try:
                entry = json.loads(line)
            except:
                continue

            # Track tool calls
            if entry.get('type') == 'assistant':
