                    if isinstance(tur, dict):
                        sc = tur.get('structuredContent')
                        if isinstance(sc, dict):
                            rs = sc.get('result', '')
                            if isinstance(rs, str):
                                try:
                                    inner2 = json.loads(rs)
                                    if isinstance(inner2, dict) and 'data' in inner2:
                                        s2 = inner2['data'].get('stdout', '')
                                        if s2 and len(s2) > len(stdout):
                                            stdout = s2
                                except:
