import json

logf = 'worker_ops_check-009e-status_20260515T100311.log'

tool_to_exp = {}
with open(logf, 'r', errors='replace') as f:
    for line_num, line in enumerate(f, 1):
        line = line.strip()
        if not line or not line.startswith('{'):
            continue
        try:
            entry = json.loads(line)
        except:
            continue

        if entry.get('type') == 'assistant':
            msg = entry.get('message')
            if not isinstance(msg, dict):
                continue
            for item in (msg.get('content') or []):
                if isinstance(item, dict) and item.get('type') == 'tool_use':
                    name = item.get('name', '')
                    cmd = (item.get('input') or {}).get('command', '')
                    if 'metrics' in cmd or 'actor_loss' in cmd or '009e' in cmd:
                        print(f'L{line_num} [{name}] ID={item.get("id","")[:25]}:')
                        print(f'  CMD: {cmd[:400]}')
                        print()
                        if 'exp_009e' in cmd:
                            tool_to_exp[item.get('id', '')] = '009e_s1'

        if entry.get('type') == 'user':
            msg = entry.get('message')
            if not isinstance(msg, dict):
                continue
            for item in (msg.get('content') or []):
                if not isinstance(item, dict) or item.get('type') != 'tool_result':
                    continue
                c = item.get('content', '')
                if not isinstance(c, str) or 'actor_loss' not in c:
                    continue
                tool_id = item.get('tool_use_id', '')
                exp = tool_to_exp.get(tool_id, 'unknown')

                try:
                    obj = json.loads(c)
                    inner = json.loads(obj['result'])
                    stdout = inner['data']['stdout']
                    count = 0
                    for sl in stdout.strip().split('\n'):
                        try:
                            sobj = json.loads(sl)
                            if 'actor_loss' in sobj:
                                count += 1
                                print(f'  {exp}: step={sobj["step"]}, actor_loss={sobj["actor_loss"]}')
                        except:
                            pass
                    print(f'  Total in this result: {count}')
                except:
                    pass
