                            continue
                        # Check if this line has step
                        m_step = re.search(r'"step":\s*(\d+)', sl)
                        m_al = re.search(r'"actor_loss":\s*([-\d.eE+]+)', sl)
                        if m_step and m_al:
                            print(f'  Line {i}: step={m_step.group(1)}, actor_loss={m_al.group(1)}')
                        else:
                            # The line might be cut off. Check surrounding lines for step
                            # Lines without step might be mid-truncation
                            print(f'  Line {i} (no step): {sl[:200]}')
                            # Check if previous lines have step context
                            if i > 0:
                                prev = lines[i-1]
                                m_prev_step = re.search(r'"step":\s*(\d+)', prev)
